package com.campusconnect.chat; import com.campusconnect.user.User; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="chat_turns",indexes=@Index(name="idx_chat_user_time",columnList="user_id,created_at")) public class ChatTurn { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private User user; @Column(nullable=false,length=8000) private String question; @Column(nullable=false,length=12000) private String answer; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); protected ChatTurn(){} public ChatTurn(User u,String q,String a){user=u;question=q;answer=a;} public Long getId(){return id;} public String getQuestion(){return question;} public String getAnswer(){return answer;} public Instant getCreatedAt(){return createdAt;} }
